{
  "jsonrpc": "2.0",
  "id": 72,
  "method": "tools/call",
  "params": {
    "name": "create_component_schema",
    "arguments": {
      "name": "Hero Banner QA",
      "meta_data": { "description": "QA test hero banner component with multiple field types" },
      "field_types": [
        {
          "name": "headline",
          "type": "short_text",
          "meta_data": { "label": { "value": "Headline" }, "placeholder": { "value": "Enter headline" } },
          "validations": { "required": { "value": true }, "max_length": { "value": 120 } }
        },
        {
          "name": "hero_image",
          "type": "media",
          "meta_data": { "label": { "value": "Hero Image" } },
          "validations": { "required": { "value": true } }
        },
        {
          "name": "cta_url",
          "type": "url",
          "meta_data": { "label": { "value": "CTA URL" } }
        },
        {
          "name": "cta_label",
          "type": "short_text",
          "meta_data": { "label": { "value": "CTA Button Label" }, "default": { "value": "Learn More" } }
        }
      ],
      "dry_run": true
    }
  }
}

